//! The tray icon. On a Mac, the menu bar icon: a monochrome template of the agent symbol, one image per state
//! (generated by `apps/desktop/scripts/icons.ts` in CI; macOS tints template images for light and dark menu
//! bars by itself), shown while this computer works for agents or when the person chose it, and opening the
//! popover. On Windows and Linux there is no Dock and closing the window only hides it, so the icon is always
//! there, the app's own, with a native menu (Linux's AppIndicator never passes clicks to the app): open the
//! app, the servers, pausing the agents here, the server here's state with Start or Stop, Preferences, quit.

use tauri::AppHandle;

const TRAY_ID: &str = "main";

#[cfg(target_os = "macos")]
mod icons {
    pub const IDLE: &[u8] = include_bytes!("../icons/tray/idle.png");
    pub const WORKING: &[u8] = include_bytes!("../icons/tray/working.png");
    pub const PAUSED: &[u8] = include_bytes!("../icons/tray/paused.png");
    pub const OFFLINE: &[u8] = include_bytes!("../icons/tray/offline.png");
    pub const UPDATE: &[u8] = include_bytes!("../icons/tray/update.png");
    /// An agent is in its browser: a ring in the corner.
    pub const BROWSING: &[u8] = include_bytes!("../icons/tray/browsing.png");
    /// An agent needs a person in its browser: a filled dot in the corner.
    pub const NEEDS: &[u8] = include_bytes!("../icons/tray/needs.png");
}

const STATES: &[&str] = &["idle", "working", "paused", "offline", "update", "browsing", "needs"];

#[cfg(target_os = "macos")]
fn bytes_for(state: &str) -> Option<&'static [u8]> {
    use icons::*;
    match state {
        "idle" => Some(IDLE),
        "working" => Some(WORKING),
        "paused" => Some(PAUSED),
        "offline" => Some(OFFLINE),
        "update" => Some(UPDATE),
        "browsing" => Some(BROWSING),
        "needs" => Some(NEEDS),
        _ => None,
    }
}

#[cfg(target_os = "macos")]
pub fn create(app: &AppHandle) -> tauri::Result<()> {
    use tauri::image::Image;
    use tauri::tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent};
    let tray = TrayIconBuilder::with_id(TRAY_ID)
        .tooltip("agentes.chat")
        .icon(Image::from_bytes(icons::IDLE)?)
        .icon_as_template(true)
        .on_tray_icon_event(|tray, event| {
            // The positioner needs every tray event to know where the icon is.
            tauri_plugin_positioner::on_tray_event(tray.app_handle(), &event);
            if let TrayIconEvent::Click {
                button: MouseButton::Left | MouseButton::Right,
                button_state: MouseButtonState::Up,
                ..
            } = event
            {
                crate::toggle_popover(tray.app_handle());
            }
        })
        .build(app)?;
    // Off until the popover says (`tray_visible`): with agentes.chat nothing of this computer shows.
    tray.set_visible(false)?;
    Ok(())
}

#[cfg(not(target_os = "macos"))]
pub fn create(app: &AppHandle) -> tauri::Result<()> {
    let mut builder = tauri::tray::TrayIconBuilder::with_id(TRAY_ID)
        .tooltip("agentes.chat")
        .menu(&menu(app)?)
        .show_menu_on_left_click(true);
    if let Some(icon) = app.default_window_icon() {
        builder = builder.icon(icon.clone());
    }
    builder.build(app)?;
    Ok(())
}

/// Windows and Linux: the tray's menu, with the labels the popover sent (each key until then).
#[cfg(not(target_os = "macos"))]
fn menu(app: &AppHandle) -> tauri::Result<tauri::menu::Menu<tauri::Wry>> {
    use tauri::menu::{Menu, MenuItemBuilder, PredefinedMenuItem, SubmenuBuilder};
    let labels = crate::menus::labels(app);
    let l = |key: &str| labels.get(key).cloned().unwrap_or_else(|| key.to_string());
    let item = |id: &str, key: &str| MenuItemBuilder::with_id(format!("app:{id}"), l(key)).build(app);
    let menu = Menu::new(app)?;
    menu.append(&item("open", "trayOpen")?)?;
    menu.append(&crate::menus::servers_menu(app, &l)?)?;
    // Agents work here (Linux): pause them for the whole computer, or resume.
    if agents_work_here(app) {
        let pause = SubmenuBuilder::new(app, l("trayPause"))
            .item(&item("pause1h", "trayPause1h")?)
            .item(&item("pauseTomorrow", "trayPauseTomorrow")?)
            .item(&item("pauseManual", "trayPauseManual")?)
            .build()?;
        menu.append(&PredefinedMenuItem::separator(app)?)?;
        menu.append(&pause)?;
        menu.append(&item("resume", "trayResume")?)?;
    }
    // The server here: its state, and Start or Stop.
    if crate::local_server::runs(app) {
        use crate::local_server::Phase;
        let phase = crate::local_server::phase(app);
        let (state, action) = match phase {
            Phase::Running => ("serverRunning", ("hereStop", "serverStop")),
            Phase::Starting | Phase::Updating | Phase::Restarting => ("serverStarting", ("hereStop", "serverStop")),
            Phase::Failing => ("serverFailing", ("hereStart", "serverStart")),
            Phase::Stopped | Phase::Off => ("serverStopped", ("hereStart", "serverStart")),
        };
        menu.append(&PredefinedMenuItem::separator(app)?)?;
        let line = format!("{} · {}", l("serverTitle"), l(state));
        menu.append(&MenuItemBuilder::new(line).enabled(false).build(app)?)?;
        menu.append(&item(action.0, action.1)?)?;
    }
    menu.append(&PredefinedMenuItem::separator(app)?)?;
    menu.append(&item("prefs", "trayPrefs")?)?;
    menu.append(&item("quit", "quit")?)?;
    Ok(menu)
}

#[cfg(not(target_os = "macos"))]
fn agents_work_here(app: &AppHandle) -> bool {
    use tauri::Manager;
    app.state::<crate::runners::Runners>().any_paired()
}

/// Whether agents worked here when the tray's menu was last built (0 no, 1 yes, 2 not built yet).
#[cfg(not(target_os = "macos"))]
static BUILT_WITH_AGENTS: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(2);

/// The tray's menu again (Windows, Linux): the labels or the servers changed.
pub fn refresh(app: &AppHandle) {
    #[cfg(not(target_os = "macos"))]
    if let (Some(tray), Ok(menu)) = (app.tray_by_id(TRAY_ID), menu(app)) {
        BUILT_WITH_AGENTS.store(u8::from(agents_work_here(app)), std::sync::atomic::Ordering::Relaxed);
        let _ = tray.set_menu(Some(menu));
    }
    // The Mac's menu bar has the server here's state and Stop or Start (menus.rs `here_menu`).
    #[cfg(target_os = "macos")]
    crate::menus::here_changed(app);
}

pub fn set_state(app: &AppHandle, state: &str) -> Result<(), String> {
    if !STATES.contains(&state) {
        return Err(format!("unknown tray state: {state}"));
    }
    #[cfg(target_os = "macos")]
    {
        let bytes = bytes_for(state).ok_or("no image")?;
        let tray = app.tray_by_id(TRAY_ID).ok_or("no tray icon")?;
        let image = tauri::image::Image::from_bytes(bytes).map_err(|e| e.to_string())?;
        tray.set_icon(Some(image)).map_err(|e| e.to_string())?;
        tray.set_icon_as_template(true).map_err(|e| e.to_string())?;
    }
    // Windows and Linux keep the app's own icon (template images are a Mac's); the menu follows whether
    // agents work here, which changes along with the state.
    #[cfg(not(target_os = "macos"))]
    if BUILT_WITH_AGENTS.load(std::sync::atomic::Ordering::Relaxed) != u8::from(agents_work_here(app)) {
        refresh(app);
    }
    Ok(())
}

/// On a Mac, whether the menu bar icon shows (the popover decides: agents here, or the person's choice).
#[tauri::command]
pub fn tray_visible(app: AppHandle, window: tauri::Window, show: bool) -> Result<(), String> {
    if !matches!(window.label(), "popover" | "prefs") {
        return Err("only the app's own windows set this".into());
    }
    #[cfg(target_os = "macos")]
    if let Some(tray) = app.tray_by_id(TRAY_ID) {
        tray.set_visible(show).map_err(|e| e.to_string())?;
    }
    #[cfg(not(target_os = "macos"))]
    let _ = (app, show);
    Ok(())
}
